size_t checks=0;void need(bool v,const char* why){++checks;if(!v)throw std::runtime_error(why);}
std::string replaced(std::string s,const std::string& from,const std::string& to){auto at=s.find(from);need(at!=std::string::npos,"mutation anchor exists");s.replace(at,from.size(),to);return s;}
std::string wire(const NativeSessionState& s){std::ostringstream o;native_runtime_wire::encode(o,s);need(bool(o),"legal synthetic wire encodes");return o.str();}
bool read(const std::string& text,NativeSessionState& s){s.rulesVersion=8;std::istringstream in(text);if(!native_runtime_wire::decode(in,s))return false;in>>std::ws;return in.eof();}
void refusesEncode(const NativeSessionState& s){std::ostringstream o;native_runtime_wire::encode(o,s);need(o.fail()&&o.str().empty(),"invalid or hidden population state never silently encodes");}
NativeSessionState oldState(unsigned version){NativeSessionState s;s.rulesVersion=8;if(version>=2){s.figureRuntime.emplace();s.observedDry.emplace();s.runtimePolicies={nativeObservedDryTag};}if(version>=3)s.runtimePolicies.push_back(nativeMigrantNonemptyTag);if(version>=4)s.runtimePolicies.push_back(nativeObservedRewaterTag);return s;}
// Independent explicit pre-population schema. Repeated zero array members are
// expanded from fixed original dimensions, never from the production visitor.
std::string zeroes(size_t n){std::string s;for(size_t i=0;i<n;++i)s+="0 ";return s;}
std::string oldGolden(unsigned version){
 if(version==1)return "RUNTIME8 1\nschedule 0 \nfigures 0 \nhook 0 \nheldHouses 0 \nheldWalkers 0 \nstrictRecords 0 \nstrictContext 0 \npolicies 0 \nobjects 0\nENDRUNTIME8\n";
 std::string s="RUNTIME8 "+std::to_string(version)+"\nschedule 0 \nfigures 1 walkers 0 \ncellHeads 0 \nfreeFIFO 0 \nhighest 0 \nservices formation "+zeroes(200)+"\nrouteOwners "+zeroes(1000)+"\ndirections 0 \nrandomFirst 0 \nrandomSecond 0 \nring 0 \ncursor 0 \nprevious 0 \nfires 0 \ncriminals 0 \nallocation 0 \nserviceGrid 0 \n\nspeechCounters "+zeroes(359)+"\nspeechCounts "+zeroes(359)+"\nspeechChoices 0 \n\nhook 0 \nheldHouses 0 \nheldWalkers 0 \nstrictRecords 0 \nstrictContext 0 \npolicies "+std::to_string(version-1)+" ";
 const char* policies[]={"native_house_observed_dry_type4_to3_v1","native_migrant_nonempty_rehousing_policy_v1","native_house_water_only_recovery_policy_v1"};
 for(unsigned i=0;i<version-1;++i)s+='"'+std::string(policies[i])+"\" ";
 return s+"\nobservedDry 1 pendingExcess 0 \ndepartedSinceMeal 0 \narrivedSinceMeal 0 \n\nmigrantPayloads 0 \nobjects 0\nENDRUNTIME8\n";
}
