void compare(const NativePopulationRuntime& a,const NativePopulationRuntime& b){
#define LABOR(x) need(a.labor.x==b.labor.x,"Labor." #x " preserved")
 LABOR(sentiment);LABOR(health);LABOR(migration);LABOR(incoming);LABOR(outgoing);LABOR(inRemainder);LABOR(outRemainder);LABOR(inDelay);LABOR(outDelay);LABOR(arrivals);LABOR(departures);LABOR(unplaced);LABOR(yearArrivals);LABOR(spacing);LABOR(statisticsPending);LABOR(populationSum);LABOR(sampleCount);LABOR(averagePopulation);LABOR(growthCursor);LABOR(deathCursor);LABOR(lastPopulationDelta);LABOR(excessDepartureTotal);LABOR(difficulty);LABOR(wageBand);LABOR(populationNotices);LABOR(hostileCount);LABOR(formationLabor);
#undef LABOR
 for(size_t i=0;i<10;++i){const auto& x=a.employment.rows[i];const auto& y=b.employment.rows[i];need(x.demand==y.demand,"employment demand rows0..9 preserved");need(x.allocated==y.allocated,"employment allocation rows0..9 preserved");need(x.preferred==y.preferred,"employment preference rows0..9 preserved");need(x.preferredAllocated==y.preferredAllocated,"employment preferred allocation rows0..9 preserved");need(x.priority==y.priority,"employment priority rows0..9 preserved");}
#define EMPLOYMENT(x) need(a.employment.x==b.employment.x,"Employment." #x " preserved")
 EMPLOYMENT(available);EMPLOYMENT(employed);EMPLOYMENT(unemployed);EMPLOYMENT(unemploymentPercent);EMPLOYMENT(shortage);EMPLOYMENT(shortageNotice);EMPLOYMENT(unemploymentNotice);
#undef EMPLOYMENT
#define LEDGER(x) need(a.x==b.x,"Population." #x " uint64 preserved")
 LEDGER(admitted);LEDGER(arrived);LEDGER(unplaced);LEDGER(populationArrived);LEDGER(populationDeparted);
#undef LEDGER
}
std::string newcomer(){OriginalFigure f;f.slot=7;f.type=11;f.alive=1;f.action=6;f.owner=0;f.home=7;f.employmentAmount=4;std::string e;auto p=encodeNativeImmigrant(f,e);need(bool(p),"synthetic type11 payload encodes");return *p;}
void legacy(){for(unsigned v=1;v<=4;++v){auto state=oldState(v);const auto expected=oldGolden(v);need(wire(state)==expected,"pre-population wire1..4 independent golden bytes unchanged");auto stale=fixture();stale.figureRuntime->immigrantPayloads={newcomer()};need(read(expected,stale)&&!stale.populationRuntime&&(!stale.figureRuntime||stale.figureRuntime->immigrantPayloads.empty()),"old versions clear stale population state and immigrants");need(wire(stale)==expected,"old wire stays old instead of becoming version5");
 auto bad=state;bad.populationRuntime.emplace();bad.populationRuntime->labor.inRemainder=1;refusesEncode(bad);bad=state;if(!bad.figureRuntime)bad.figureRuntime.emplace();bad.figureRuntime->immigrantPayloads={newcomer()};refusesEncode(bad);}}
void population(){auto s=fixture();s.figureRuntime->immigrantPayloads={newcomer()};const auto bytes=wire(s);need(bytes.rfind("RUNTIME8 5\n",0)==0,"explicit population policy chooses wire5");need(bytes.find("migrantPayloads ")<bytes.find("populationRuntime ")&&bytes.find("populationRuntime ")<bytes.find("immigrantPayloads ")&&bytes.find("immigrantPayloads ")<bytes.find("objects "),"population extension follows old dry fields before object rows");
 NativeSessionState back;need(read(bytes,back)&&back.populationRuntime&&back.figureRuntime,"wire5 restores explicit population state");compare(*s.populationRuntime,*back.populationRuntime);need(back.figureRuntime->immigrantPayloads==s.figureRuntime->immigrantPayloads&&wire(back)==bytes,"wire5 retains type11 bytes and exact canonical wire");std::string e;auto f=decodeNativeImmigrant(back.figureRuntime->immigrantPayloads.front(),e);need(f&&f->type==11&&f->home==7&&f->employmentAmount==4,"wire5 framing carries actual newcomer family");
 for(int mode=0;mode<3;++mode){auto variant=s;if(mode==0){variant.populationRuntime->labor.populationNotices.reset();variant.populationRuntime->employment.shortageNotice.reset();variant.populationRuntime->employment.unemploymentNotice.reset();}else{std::array<bool,10> notices{};notices.fill(mode==2);variant.populationRuntime->labor.populationNotices=notices;variant.populationRuntime->employment.shortageNotice=mode==2;variant.populationRuntime->employment.unemploymentNotice=mode==1;}const auto encoded=wire(variant);NativeSessionState restored;need(read(encoded,restored)&&restored.populationRuntime,"optional notice fixture reads");compare(*variant.populationRuntime,*restored.populationRuntime);}
 auto wide=s;auto& p=*wide.populationRuntime;p.admitted=399900000000000ULL;p.arrived=399899999999999ULL;p.unplaced=1;p.populationArrived=399900000000000ULL;p.populationDeparted=399900000000000ULL;p.labor.deathCursor=INT16_MIN;p.labor.sentiment=INT32_MIN;p.labor.inRemainder=INT32_MAX;p.labor.inDelay=INT32_MAX;p.labor.formationLabor={INT32_MIN,INT32_MAX,-1,0};p.employment.rows[9]={INT32_MIN,INT32_MAX,INT32_MIN,INT32_MAX,INT32_MIN};const auto wideBytes=wire(wide);NativeSessionState extremes;need(read(wideBytes,extremes)&&extremes.populationRuntime,"wire preserves accepted large counters and signed fields without narrowing");compare(p,*extremes.populationRuntime);
 auto reject=[&](const std::string& b){NativeSessionState out;need(!read(b,out),"bad population schema/version/width refuses");};
 for(unsigned v:{1,2,3,4,6})reject(replaced(bytes,"RUNTIME8 5\n","RUNTIME8 "+std::to_string(v)+"\n"));
 reject(replaced(bytes,nativeImmigrationTag,"native_population_immigrant11_policy_v99"));reject(replaced(bytes,"populationRuntime 1 labor ","populationRuntime 0 labor "));reject(replaced(bytes,"incoming 17 ","incoming 2147483648 "));reject(replaced(bytes,"deathCursor -17 ","deathCursor 32768 "));reject(replaced(bytes,"deathCursor -17 ","deathCursor -32769 "));reject(replaced(bytes,"admitted 123456789012345 ","admitted 18446744073709551616 "));reject(replaced(bytes,"admitted 123456789012345 ","admitted -1 "));reject(replaced(bytes,"incoming 17 \n","incoming 17 \nincoming 17 \n"));reject(replaced(bytes,"statisticsPending ","unknownStatistics "));reject(replaced(bytes,"immigrantPayloads 1 ","immigrantPayloads 500001 "));reject(bytes+"trailing");reject(bytes.substr(0,bytes.size()-5));
 auto duplicate=s;duplicate.observedDry->pendingExcess={{7,4}};reject(replaced(wire(duplicate),"pendingExcess 1 7 4 ","pendingExcess 2 7 4 7 5 "));
 const std::string policies="policies 4 \"native_house_observed_dry_type4_to3_v1\" \"native_migrant_nonempty_rehousing_policy_v1\" \"native_house_water_only_recovery_policy_v1\" \"native_population_immigrant11_policy_v1\" ";
 const std::string oldPolicies="policies 3 \"native_house_observed_dry_type4_to3_v1\" \"native_migrant_nonempty_rehousing_policy_v1\" \"native_house_water_only_recovery_policy_v1\" ";reject(replaced(bytes,policies,oldPolicies));reject(replaced(oldGolden(4),"RUNTIME8 4\n","RUNTIME8 5\n"));
 auto missing=s;missing.populationRuntime.reset();refusesEncode(missing);missing=s;missing.runtimePolicies.erase(std::remove(missing.runtimePolicies.begin(),missing.runtimePolicies.end(),nativeImmigrationTag),missing.runtimePolicies.end());refusesEncode(missing);missing=s;missing.runtimePolicies.erase(std::remove(missing.runtimePolicies.begin(),missing.runtimePolicies.end(),nativeObservedRewaterTag),missing.runtimePolicies.end());refusesEncode(missing);missing=s;missing.figureRuntime.reset();refusesEncode(missing);missing=s;missing.rulesVersion=7;refusesEncode(missing);
 for(const auto& badPayload:{std::string{},std::string(16385,'x'),std::string("x\0y",3)}){auto bad=s;bad.figureRuntime->immigrantPayloads={badPayload};refusesEncode(bad);}auto over=s;over.figureRuntime->immigrantPayloads.assign(2000,newcomer());refusesEncode(over);
}
NativeSessionSeed seed(){NativeSessionSeed s;s.source="population-test.sav";s.sourceRevision=1;s.modelRevision=2;s.side=8;s.initialFunds=1000;s.roadCost=2;s.houseCost=15;s.houseCapacity=7;s.wellCost=25;s.hunterCost=32;s.laborPercent=50;s.hunterWorkers=2;s.wellWorkers=4;s.laborPriority.fill(3);s.houseCapacities={{0,7},{1,14},{2,14},{4,21}};s.buildable.assign(64,1);s.sourceRoad.assign(64,0);for(int i=0;i<15;++i){std::array<int32_t,24> row{};row[17]=i==1?14:7;s.houseModels[i]=row;}return s;}
void publicContracts(){const auto model=seed();auto s=oldState(4);s.funds=model.initialFunds;s.runtimePolicies.push_back(nativeImmigrationTag);s.populationRuntime.emplace();s.populationRuntime->labor.sentiment=60;s.populationRuntime->labor.health=80;s.populationRuntime->labor.statisticsPending=0;s.populationRuntime->labor.difficulty=2;s.populationRuntime->labor.wageBand=3;s.populationRuntime->labor.populationNotices=std::array<bool,10>{};s.houseSchedule.emplace();auto& f=*s.figureRuntime;f.cellHeads.assign(51984,0);f.services.directions.assign(500000,0);f.services.serviceGrid.assign(51984,0);f.highestFigureSlot=0;for(uint16_t n=1;n<2000;++n)f.freeFigureSlots.push_back(n);s.buildingHookCountdown=0;need(validateNativeSession(model,s).empty(),"complete synthetic empty population ledger admitted");const auto bytes=encodeNativeSession(model,s);std::string error;auto loaded=decodeNativeSession(model,bytes,error);need(!bytes.empty()&&loaded&&loaded->populationRuntime&&encodeNativeSession(model,*loaded)==bytes,"public ENCITY roundtrip includes version5 state");
 auto boundary=s;auto& limits=*boundary.populationRuntime;limits.admitted=399900000000000ULL;limits.arrived=399900000000000ULL;limits.populationArrived=399900000000000ULL;limits.populationDeparted=399900000000000ULL;limits.labor.spacing=10000000;need(validateNativeSession(model,boundary).empty(),"accepted cumulative and spacing upper bounds are legal");const auto boundaryBytes=encodeNativeSession(model,boundary);auto boundaryRead=decodeNativeSession(model,boundaryBytes,error);need(boundaryRead&&boundaryRead->populationRuntime&&boundaryRead->populationRuntime->admitted==399900000000000ULL,"accepted cumulative bound persists through public wire");boundary.populationRuntime->arrived=0;boundary.populationRuntime->unplaced=399900000000000ULL;need(validateNativeSession(model,boundary).empty(),"unplaced at accepted bound is legal with matching admission");
 for(unsigned which=0;which<5;++which){auto bad=s;auto& counts=*bad.populationRuntime;switch(which){case 0:counts.admitted=UINT64_MAX;break;case 1:counts.arrived=UINT64_MAX;break;case 2:counts.unplaced=UINT64_MAX;break;case 3:counts.populationArrived=UINT64_MAX;break;default:counts.populationDeparted=UINT64_MAX;}need(!validateNativeSession(model,bad).empty()&&encodeNativeSession(model,bad).empty(),"MAX cumulative population counter cannot be published");}
 for(int32_t spacing:{int32_t(-1),int32_t(10000001)}){auto bad=s;bad.populationRuntime->labor.spacing=spacing;need(!validateNativeSession(model,bad).empty()&&encodeNativeSession(model,bad).empty(),"labor spacing outside0..10000000 refused");}
 for(int which=0;which<4;++which){auto bad=s;auto& p=*bad.populationRuntime;if(which==0)p.populationArrived=1;if(which==1)p.populationDeparted=1;if(which==2){p.admitted=3;p.arrived=4;}if(which==3){p.admitted=3;p.arrived=2;p.unplaced=2;}need(!validateNativeSession(model,bad).empty()&&encodeNativeSession(model,bad).empty(),"invalid cumulative/arrival ledger cannot be saved");}
 for(bool incoming:{false,true}){auto bad=s;if(incoming)bad.populationRuntime->labor.inDelay=INT32_MIN;else bad.populationRuntime->labor.outDelay=INT32_MIN;need(!validateNativeSession(model,bad).empty()&&encodeNativeSession(model,bad).empty(),"negative decrementing delay refused before updater");}
 for(unsigned version=1;version<=7;++version){auto old=startNativeSession(model,version);need(validateNativeSession(model,old).empty(),"legacy control is independently legal");old.populationRuntime.emplace();old.populationRuntime->labor.inDelay=1;need(!validateNativeSession(model,old).empty()&&encodeNativeSession(model,old).empty(),"legacy rules1..7 refuse hidden nondefault population state");}
}
