int main(){try{legacy();population();publicContracts();std::cout<<"{\"population_wire_checks\":"<<checks<<",\"labor_fields\":27,\"employment_rows\":10,\"legacy_wire_goldens\":4,\"passed\":true,\"synthetic_only\":true}\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL:"<<e.what()<<"\n";return 1;}}
